import { z } from 'zod';

// 1. Create the Zod Schema (The Runtime Guard)
const UserSchema = z.object({
  username: z.string().min(3, "Must be at least 3 chars"),
  age: z.number().positive(),
  email: z.string().email().optional()
});

// 2. EXTRACT THE TS TYPE (The magic trick! No duplicate typing needed)
type User = z.infer<typeof UserSchema>;

// 3. Validate runtime data (e.g., from an API or Form)
const incomingApiData = {
  username: "Al",
  age: -5
};

// safeParse protects the app from crashing
const result = UserSchema.safeParse(incomingApiData);

if (!result.success) {
  console.error("Validation failed!", result.error.issues);
} else {
  // Inside here, TS knows result.data perfectly matches the 'User' type!
  console.log("Valid user:", result.data.username);
}
